import re

def parse_boxes():
    with open("/app/dataset/genealogy_trees.txt", "r") as f:
        lines = [line.rstrip("\n") for line in f]

    segments = []
    for r, line in enumerate(lines):
        for match in re.finditer(r"[A-Za-zĄĆĘŁŃÓŚŹŻąćęłńóśźż]{2,}(?:\s+[A-Za-zĄĆĘŁŃÓŚŹŻąćęłńóśźż]+)*", line):
            segments.append({
                "row": r,
                "c_start": match.start(),
                "c_end": match.end(),
                "text": match.group()
            })

    groups = []
    used = set()
    for i, seg in enumerate(segments):
        if i in used:
            continue
        group = [seg]
        used.add(i)
        added = True
        while added:
            added = False
            for j, other in enumerate(segments):
                if j in used:
                    continue
                for member in group:
                    if abs(member["row"] - other["row"]) <= 1:
                        overlap = max(0, min(member["c_end"], other["c_end"]) - max(member["c_start"], other["c_start"]))
                        if overlap > 0 or (member["row"] == other["row"] and abs(member["c_end"] - other["c_start"]) <= 2):
                            group.append(other)
                            used.add(j)
                            added = True
                            break
        groups.append(group)

    reconstructed = []
    for idx, group in enumerate(groups):
        group.sort(key=lambda x: (x["row"], x["c_start"]))
        row_texts = {}
        for member in group:
            r = member["row"]
            if r not in row_texts:
                row_texts[r] = []
            row_texts[r].append(member)
        sorted_rows = sorted(row_texts.keys())
        full_name_parts = []
        for r in sorted_rows:
            row_text = " ".join([m["text"] for m in row_texts[r]])
            full_name_parts.append(row_text)
        full_name = " ".join(full_name_parts)

        min_row = min(m["row"] for m in group)
        max_row = max(m["row"] for m in group)
        min_col = min(m["c_start"] for m in group)
        max_col = max(m["c_end"] for m in group)

        reconstructed.append({
            "id": idx,
            "name": full_name,
            "min_row": min_row,
            "max_row": max_row,
            "min_col": min_col,
            "max_col": max_col
        })
    return reconstructed, lines

def find_box_by_name(boxes, name):
    for b in boxes:
        if b["name"] == name:
            return b
    return None

def trace_up_from_box(start_box, boxes, lines):
    # We want to find the vertical line going up from the top border of start_box
    # The top border of start_box is at start_box["min_row"] - 1
    r = start_box["min_row"] - 1

    v_chars = set(['|', '│', 'I', 'l', '\\', '/'])
    h_chars = set(['-', '~', '_', '+', '┐', '┌', '┘', '└', '┤', '├', '┬', '┴', '┼'])

    start_c = None
    for c in range(start_box["min_col"] - 2, start_box["max_col"] + 3):
        if r >= 0 and c < len(lines[r]) and lines[r][c] in v_chars:
            start_c = c
            break
        if r >= 0 and c < len(lines[r]) and lines[r][c] == '+':
            start_c = c
            break

    if start_c is None:
        for c in range(start_box["min_col"] - 2, start_box["max_col"] + 3):
            if r-1 >= 0 and c < len(lines[r-1]) and lines[r-1][c] in v_chars:
                start_c = c
                r = r - 1
                break

    if start_c is None:
        print(f"Could not find starting vertical line for {start_box['name']}")
        return None

    c = start_c
    print(f"Tracing up from {start_box['name']} starting at row {r+1}, col {c}")

    while r >= 0:
        # Check if we are currently AT or NEXT to the bottom of any box
        # We check both the current r and r-1 (if we can step onto it as a bottom border)
        for box in boxes:
            if box["id"] == start_box["id"]:
                continue
            # Bottom border is at box["max_row"] + 1
            bottom_row = box["max_row"] + 1
            if r == bottom_row and box["min_col"] - 3 <= c <= box["max_col"] + 3:
                print(f"  Hit bottom of box {box['name']} at row {r+1}, col {c}")
                return box
            if r - 1 == bottom_row and box["min_col"] - 3 <= c <= box["max_col"] + 3:
                print(f"  Hit bottom of box {box['name']} at row {r}, col {c} (via step)")
                return box

        # Check if we can move up
        char_curr = lines[r][c] if c < len(lines[r]) else ' '
        char_above = lines[r-1][c] if r-1 >= 0 and c < len(lines[r-1]) else ' '

        if char_above in v_chars or char_above == '|' or char_above == '│':
            r -= 1
            continue

        # If we cannot move up directly, are we on a corner or horizontal line?
        print(f"  Encountered corner/horizontal line at row {r+1}, col {c}: {repr(char_curr)}")
        h_cols = []
        # Go left
        cl = c
        while cl >= 0 and cl < len(lines[r]) and (lines[r][cl] in h_chars or lines[r][cl] in v_chars or lines[r][cl] == ' '):
            if lines[r][cl] == ' ' and (cl-1 < 0 or lines[r][cl-1] == ' '):
                break
            h_cols.append(cl)
            cl -= 1
        # Go right
        cr = c + 1
        while cr < len(lines[r]) and (lines[r][cr] in h_chars or lines[r][cr] in v_chars or lines[r][cr] == ' '):
            if lines[r][cr] == ' ' and (cr+1 >= len(lines[r]) or lines[r][cr+1] == ' '):
                break
            h_cols.append(cr)
            cr += 1

        h_cols = sorted(list(set(h_cols)))
        print(f"  Horizontal segment spans columns {min(h_cols)} to {max(h_cols)}")

        # Look for any vertical line going UP (row r-1 has v_char)
        found_up = False
        for col in h_cols:
            char_up = lines[r-1][col] if r-1 >= 0 and col < len(lines[r-1]) else ' '
            if char_up in v_chars or char_up == '|' or char_up == '│':
                print(f"  Found vertical branch going UP at row {r}, col {col}")
                r -= 1
                c = col
                found_up = True
                break

        if not found_up:
            for col in h_cols:
                char_up = lines[r-1][col] if r-1 >= 0 and col < len(lines[r-1]) else ' '
                if char_up == '+':
                    print(f"  Found vertical branch (corner) going UP at row {r}, col {col}")
                    r -= 1
                    c = col
                    found_up = True
                    break

        if not found_up:
            # Let's check if the row r-1 touches the bottom of any box!
            for col in h_cols:
                for box in boxes:
                    if box["id"] == start_box["id"]:
                        continue
                    if r - 1 == box["max_row"] + 1 and box["min_col"] - 3 <= col <= box["max_col"] + 3:
                        print(f"  Found connection directly to bottom of box {box['name']} at row {r}, col {col}")
                        return box

        if not found_up:
            print(f"  No upward branch found on horizontal line at row {r+1}")
            return None

    return None

if __name__ == "__main__":
    boxes, lines = parse_boxes()
    dawid = find_box_by_name(boxes, "Dawid Majtyka")
    if dawid:
        curr = dawid
        for gen in range(1, 5):
            parent = trace_up_from_box(curr, boxes, lines)
            if parent:
                print(f"GEN {gen}: {parent['name']}")
                curr = parent
            else:
                print(f"Failed to trace parent at GEN {gen}")
                break
    else:
        print("Dawid Majtyka not found!")

