            "min_col": min_col,
            "max_col": max_col
        })
    return reconstructed, lines

def trace_up_from_box(start_box, boxes, lines):
    r = start_box["min_row"] - 1

    v_chars = set(['|', '│', 'I', 'l', '\\', '/'])
    h_chars = set(['-', '~', '_', '+', '┐', '┌', '┘', '└', '┤', '├', '┬', '┴', '┼'])

    start_c = None
    for c in range(start_box["min_col"] - 2, start_box["max_col"] + 3):
        if r >= 0 and c < len(lines[r]) and lines[r][c] in v_chars:
            start_c = c
            break
        if r >= 0 and c < len(lines[r]) and lines[r][c] == '+':
            start_c = c
            break

    if start_c is None:
        for c in range(start_box["min_col"] - 2, start_box["max_col"] + 3):
            if r-1 >= 0 and c < len(lines[r-1]) and lines[r-1][c] in v_chars:
                start_c = c
                r = r - 1
                break

    if start_c is None:
        return None

    c = start_c

    while r >= 0:
        for box in boxes:
            if box["id"] == start_box["id"]:
                continue
            for offset in [1, 2, 3]:
                bottom_row = box["max_row"] + offset
                if r == bottom_row and box["min_col"] - 4 <= c <= box["max_col"] + 4:
                    char_here = lines[r][c] if c < len(lines[r]) else ' '
                    if char_here in h_chars or char_here in v_chars or char_here == '│':
                        return box

        char_curr = lines[r][c] if c < len(lines[r]) else ' '
        char_above = lines[r-1][c] if r-1 >= 0 and c < len(lines[r-1]) else ' '

        if char_above in v_chars or char_above == '|' or char_above == '│':
            r -= 1
            continue

        h_cols = []
        cl = c
        while cl >= 0 and cl < len(lines[r]) and (lines[r][cl] in h_chars or lines[r][cl] in v_chars or lines[r][cl] == ' '):
            if lines[r][cl] == ' ' and (cl-1 < 0 or lines[r][cl-1] == ' '):
                break
            h_cols.append(cl)
            cl -= 1
        cr = c + 1
        while cr < len(lines[r]) and (lines[r][cr] in h_chars or lines[r][cr] in v_chars or lines[r][cr] == ' '):
            if lines[r][cr] == ' ' and (cr+1 >= len(lines[r]) or lines[r][cr+1] == ' '):
                break
            h_cols.append(cr)
            cr += 1

        h_cols = sorted(list(set(h_cols)))

        found_up = False
        for col in h_cols:
            char_up = lines[r-1][col] if r-1 >= 0 and col < len(lines[r-1]) else ' '
            if char_up in v_chars or char_up == '|' or char_up == '│':
                r -= 1
                c = col
                found_up = True
                break

        if not found_up:
            for col in h_cols:
                char_up = lines[r-1][col] if r-1 >= 0 and col < len(lines[r-1]) else ' '
                if char_up == '+':
                    r -= 1
                    c = col
                    found_up = True
                    break

        if not found_up:
            for col in h_cols:
                for box in boxes:
                    if box["id"] == start_box["id"]:
                        continue
                    for offset in [1, 2, 3]:
                        if r - 1 == box["max_row"] + offset and box["min_col"] - 4 <= col <= box["max_col"] + 4:
                            return box

        if not found_up:
            return None

    return None

def answer() -> int:
    boxes, lines = parse_boxes()

    # 1. Build parent-child mapping
    parent_of = {}
    children_of = {}
    for box in boxes:
        parent = trace_up_from_box(box, boxes, lines)
        if parent:
            parent_of[box["id"]] = parent
            children_of.setdefault(parent["id"], []).append(box)

    # 2. Find Dawid Majtyka
    dawid = next((b for b in boxes if b["name"] == "Dawid Majtyka"), None)
    if not dawid:
        raise ValueError("Dawid Majtyka not found!")

    # 3. Go up 4 generations to get great-great-grandparent
    curr = dawid
    for gen in range(4):
        if curr["id"] in parent_of:
            curr = parent_of[curr["id"]]
        else:
            raise ValueError(f"Ancestry broken at generation {gen+1} from Dawid Majtyka")

    gggp = curr

    # 4. Find all direct children of gggp
    direct_children = children_of.get(gggp["id"], [])

    # 5. Load balances from CSV
    balances = {}
    with open("/app/dataset/people_accounts.csv", "r", encoding="utf-8") as f:
        reader = csv.reader(f)
        next(reader) # skip header
        for row in reader:
            if len(row) >= 3:
                first, last, bal = row[0], row[1], int(row[2])
                balances[f"{first} {last}"] = bal

    # 6. For each direct child, count grandchildren
    total_balance = 0
    for child in direct_children:
        grandchildren = children_of.get(child["id"], [])
        grandchildren_of_child = []
        for gc in grandchildren:
            grandchildren_of_child.extend(children_of.get(gc["id"], []))

        gc_count = len(grandchildren_of_child)
        if gc_count > 1:
            total_balance += balances.get(child["name"], 0)

    return total_balance

if __name__ == "__main__":
    ans = answer()
    with open("/app/answer.json", "w") as f:
        json.dump(ans, f, default=list)
